@Transactional
public PaymentResponse processPayment(PaymentRequest req) {
    // Atomic check for idempotency
    if (idempotencyRepo.existsById(req.getIdempotencyKey())) {
        return idempotencyRepo.findById(req.getIdempotencyKey()).getResponse();
    }

    // Local ACID transaction
    Payment p = paymentRepo.save(new Payment(req, Status.PENDING));
    outboxRepo.save(new OutboxEvent("PAYMENT_CREATED", p));

    return new PaymentResponse(p.getId(), "PENDING");
}
